mapper.select:
SELECT a.employee_id, a.quota_remain, a.quota_used, a.disabled_flag, a.update_time, a.create_time, e.actual_name AS employee_name FROM t_ai_user_account a LEFT JOIN t_employee e ON a.employee_id = e.employee_id
AND a.employee_id = #{queryForm.employeeId}
AND INSTR(e.actual_name, #{queryForm.employeeName})
AND a.disabled_flag = #{queryForm.disabledFlag}
ORDER BY a.create_time DESC

mapper.update:
UPDATE t_ai_user_account
SET quota_remain = quota_remain - #{amount},
    quota_used = quota_used + #{amount}
WHERE employee_id = #{employeeId}
  AND quota_remain >= #{amount}

UPDATE t_ai_user_account
SET quota_remain = quota_remain + #{amount},
    quota_used = quota_used - #{amount}
WHERE employee_id = #{employeeId}
